static void Check(bool v,string s) { if (!v) throw new Exception(s); }
var window = new WindowSnapshot { Visible=true, Maximized=true, NativeKnown=true, HasForeground=true, Foreground=false, RootOffscreen=true, RootOffscreenKnown=true, Frame=new ScreenBox(0,0,1000,800) };
var button = new ScreenBox(50,50,200,40);
Check(BackgroundPolicy.CanScan(window) && BackgroundPolicy.Eligible(window,true,true,true,button), "covered background offscreen hint is not a hard rejection");
Check(!BackgroundPolicy.ProvesHiddenEnd(window,true), "occlusion cannot prove request completion");
Check(!BackgroundPolicy.ProvesAbsence(window,100), "root provider uncertainty cannot rearm");
Check(!BackgroundPolicy.Eligible(window,false,true,true,button) && !BackgroundPolicy.Eligible(window,true,false,true,button), "disabled/non-invoke never accepted");
Check(!BackgroundPolicy.Eligible(window,true,true,true,new ScreenBox(1200,50,100,30)) && !BackgroundPolicy.Eligible(window,true,true,true,new ScreenBox(0,0,0,0)), "out of frame or empty geometry rejected");
window.Minimized=true; window.Frame=default;
Check(BackgroundPolicy.CanScan(window) && BackgroundPolicy.Eligible(window,true,true,true,default), "minimized scan and root-scoped Invoke do not require screen coordinates");
Func<bool> missingVisibility = () => throw new InvalidOperationException("provider offscreen property unavailable");
Func<ScreenBox> missingBounds = () => throw new InvalidOperationException("provider bounding rectangle unavailable");
Check(BackgroundPolicy.EligibleFromProperties(window,true,true,missingVisibility,missingBounds), "minimized acceptance must not query unavailable screen properties");
Check(!BackgroundPolicy.EligibleFromProperties(window,false,true,missingVisibility,missingBounds) && !BackgroundPolicy.EligibleFromProperties(window,true,false,missingVisibility,missingBounds), "minimized disabled/non-Invoke rejected without geometry query");
window.ModalBlocked=true; Check(!BackgroundPolicy.EligibleFromProperties(window,true,true,missingVisibility,missingBounds), "modal blocker still rejects minimized target without querying geometry"); window.ModalBlocked=false;
Check(!BackgroundPolicy.Eligible(window,false,true,true,default) && !BackgroundPolicy.Eligible(window,true,false,true,default), "minimized still requires enabled and Invoke");
Check(!BackgroundPolicy.ProvesAbsence(window,100) && !BackgroundPolicy.ProvesHiddenEnd(window,true), "minimized does not prove lifecycle completion");
window.Foreground=true; Check(!BackgroundPolicy.CanScan(window), "inconsistent minimized foreground pauses"); window.Foreground=false;
window.Minimized=false; window.Frame=new ScreenBox(0,0,1000,800);
int screenReads=0;
Check(BackgroundPolicy.EligibleFromProperties(window,true,true,()=>{screenReads++;return true;},()=>{screenReads++;return button;}) && screenReads==2,"working covered-window screen validation preserved");
Check(!BackgroundPolicy.EligibleFromProperties(window,true,true,()=>false,()=>new ScreenBox(1200,50,100,30)),"covered-window out-of-frame rejection preserved");
string rejected;
Check(!BackgroundPolicy.EligibleFromProperties(window,true,true,()=>false,()=>default,out rejected) && rejected=="EMPTY_BOUNDS", "empty provider geometry is logged explicitly");
Check(!BackgroundPolicy.EligibleFromProperties(window,true,true,()=>false,()=>new ScreenBox(1200,50,100,30),out rejected) && rejected=="OUTSIDE_FRAME", "out-of-frame rejection reason is explicit");
window.Cloaked=true; Check(!BackgroundPolicy.CanScan(window), "cloaked pauses"); window.Cloaked=false;
window.Visible=false; Check(!BackgroundPolicy.CanScan(window), "hidden pauses"); window.Visible=true;
window.HasForeground=false; Check(!BackgroundPolicy.CanScan(window), "no active desktop pauses"); window.HasForeground=true;
window.Foreground=true; Check(!BackgroundPolicy.CanScan(window), "foreground offscreen remains conservative");
window.RootOffscreen=false; Check(BackgroundPolicy.Eligible(window,true,true,false,button) && !BackgroundPolicy.Eligible(window,true,true,true,button), "foreground behavior preserved");
Check(BackgroundPolicy.ProvesHiddenEnd(window,true) && BackgroundPolicy.ProvesAbsence(window,100) && !BackgroundPolicy.ProvesAbsence(window,1), "foreground hidden boundary / nonempty tree");
window.Frame=new ScreenBox(-1000,0,1000,800); Check(BackgroundPolicy.Eligible(window,true,true,false,new ScreenBox(-900,20,100,30)), "negative monitor coordinates");
Check(!BackgroundPolicy.Eligible(window,true,true,false,new ScreenBox(double.NaN,0,100,30)), "invalid geometry");
Check(BackgroundPolicy.NewCycle(true,false,true) && !BackgroundPolicy.NewCycle(false,false,true) && !BackgroundPolicy.NewCycle(true,true,true), "new identity requires completed scan and old identity absent");
var gate=new AutoGate(); gate.SetEnabled(true); long epoch=gate.GetEpoch().Value;
Check(gate.TryBegin(epoch,"old"), "first covered approval");
gate.Observe(epoch,true); Check(!gate.TryBegin(epoch,"old"), "still covered does not repeat");
if (BackgroundPolicy.NewCycle(true,false,true)) gate.Completed();
Check(gate.Enabled && gate.TryBegin(epoch,"new"), "next verified background request keeps ON");
var minimizedGate=new AutoGate(); minimizedGate.SetEnabled(true); long minEpoch=minimizedGate.GetEpoch().Value;
window.Minimized=true; window.Foreground=false; window.RootOffscreen=false; window.Frame=default;
Check(minimizedGate.TryBegin(minEpoch,"min-old"),"first minimized approval");
for (int i=0;i<3;i++) minimizedGate.Observe(minEpoch,!BackgroundPolicy.ProvesAbsence(window,100));
Check(minimizedGate.AwaitingAbsence && !minimizedGate.TryBegin(minEpoch,"min-old"),"minimized disappearance/offscreen hints cannot cause a duplicate");
if (BackgroundPolicy.NewCycle(true,false,true)) minimizedGate.Completed();
Check(minimizedGate.TryBegin(minEpoch,"min-new") && minimizedGate.Enabled,"complete distinct minimized request allows next approval and keeps ON");
minimizedGate.SetEnabled(false); Check(!minimizedGate.TryBegin(minEpoch,"third"),"OFF cancels minimized scan epoch");
Console.WriteLine("PASS: background visibility/geometry/lifecycle policy scenarios; no foreground activation API used.");
